import{_ as t,o as i,c as a,al as o}from"./chunks/framework.7vp1BMOE.js";const p=JSON.parse('{"title":"AI Coding Assistants","description":"","frontmatter":{},"headers":[],"relativePath":"en/contribute/ai_assistants.md","filePath":"en/contribute/ai_assistants.md"}'),n={name:"en/contribute/ai_assistants.md"};function s(r,e,l,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="ai-coding-assistants" tabindex="-1">AI Coding Assistants <a class="header-anchor" href="#ai-coding-assistants" aria-label="Permalink to &quot;AI Coding Assistants&quot;">​</a></h1><p>AI-assisted contributions are welcome in PX4. AI coding assistants are development tools, like compilers and static analyzers, and contributions made with their help are held to exactly the same standard as any other contribution: the <a href="./../contribute/code">coding standards</a>, <a href="https://github.com/PX4/PX4-Autopilot/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">commit conventions</a>, testing requirements, and review process apply unchanged.</p><p>This page defines the additional rules that apply when AI tools are used. They exist to keep authorship, accountability, and licensing unambiguous, and to keep review manageable for maintainers.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Using AI tools is optional. Disclosing their use is not.</p></div><h2 id="authorship-and-accountability" tabindex="-1">Authorship and Accountability <a class="header-anchor" href="#authorship-and-accountability" aria-label="Permalink to &quot;Authorship and Accountability&quot;">​</a></h2><p>The human submitter is the author of the contribution.</p><ul><li>You must understand every line you submit, be able to explain it, and be prepared to defend it in review.</li><li>Responsibility for correctness, safety, licensing, and testing never transfers to a tool. PX4 is safety-critical software that flies real vehicles; &quot;the AI wrote it&quot; is never an acceptable answer in review.</li><li>An AI tool is never an author or co-author. Do not add <code>Co-Authored-By</code> tags naming an AI tool.</li></ul><h2 id="signed-off-by-and-the-developer-certificate-of-origin" tabindex="-1">Signed-off-by and the Developer Certificate of Origin <a class="header-anchor" href="#signed-off-by-and-the-developer-certificate-of-origin" aria-label="Permalink to &quot;Signed-off-by and the Developer Certificate of Origin&quot;">​</a></h2><p>A <code>Signed-off-by</code> tag is the human author&#39;s certification under the <a href="https://developercertificate.org/" target="_blank" rel="noreferrer">Developer Certificate of Origin</a>.</p><ul><li>An AI tool is never the author of a contribution and must never appear in a <code>Signed-off-by</code> tag.</li><li>Tooling acting on your instruction, including an AI agent, may apply your sign-off mechanically, the same way <code>git commit -s</code> does. The certification remains yours.</li><li>By signing off you certify that you have personally reviewed the contribution and have the right to submit it under the project license. Never allow your sign-off to be applied to changes you have not reviewed.</li></ul><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><p>All code contributions must be compatible with the <a href="./../contribute/licenses">BSD 3-clause license</a> and must not impose any further constraints.</p><p>When using AI tools you are additionally responsible for the conditions of the <a href="https://www.linuxfoundation.org/legal/generative-ai" target="_blank" rel="noreferrer">Linux Foundation Generative AI Policy</a>:</p><ul><li>The terms of service of the AI tool you use must not conflict with the project license.</li><li>If the tool&#39;s output includes pre-existing copyrighted material from a third party, you must have the right to submit it, and must include the required notice, attribution, and license information.</li></ul><h2 id="disclosure-required" tabindex="-1">Disclosure (Required) <a class="header-anchor" href="#disclosure-required" aria-label="Permalink to &quot;Disclosure (Required)&quot;">​</a></h2><p>Every commit that contains AI-generated or AI-assisted content (code, documentation, or commit message text) must carry a disclosure trailer in the commit message body:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Assisted-by: NAME:MODEL</span></span></code></pre></div><p><code>NAME</code> identifies the tool and <code>MODEL</code> the specific model used, for example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Assisted-by: Claude:claude-fable-5</span></span>
<span class="line"><span>Assisted-by: Copilot:gpt-5</span></span></code></pre></div><ul><li>Conventional development tooling does not need to be disclosed: compilers, formatters (<code>make format</code>), linters, git, and classic editor autocomplete are not AI assistance in this sense.</li><li>Like the sign-off, disclosure operates on good faith: reviewers cannot reliably detect AI usage and will not try to. Undisclosed AI use discovered after the fact is treated as a misrepresentation and is grounds for reverting the contribution.</li></ul><h2 id="expectations" tabindex="-1">Expectations <a class="header-anchor" href="#expectations" aria-label="Permalink to &quot;Expectations&quot;">​</a></h2><p>These rules keep review sustainable. Contributions that ignore them may be closed by maintainers without detailed review.</p><ul><li><strong>Test claims must be real.</strong> The <a href="https://github.com/PX4/PX4-Autopilot/blob/main/CONTRIBUTING.md#test-your-changes" target="_blank" rel="noreferrer">testing requirements</a> apply unchanged: state exactly what you ran (SITL, bench test, flight test) and provide logs where they apply. Never let a tool describe testing that did not happen. An AI cannot have flown your vehicle.</li><li><strong>No unsolicited bulk changes.</strong> Do not submit large AI-generated refactors, style sweeps, or &quot;cleanup&quot; pull requests that nobody asked for. Discuss the idea in an issue or on the <a href="./../contribute/dev_call">dev call</a> first.</li><li><strong>Issues and security reports must be human-verified.</strong> Reproduce the problem yourself before filing. Unverified AI-generated findings cost maintainers real time and erode trust.</li><li><strong>Review discussion is between humans.</strong> Using an AI tool to help you understand a review comment is fine; posting model output you do not understand as your reply is not. AI-assisted review is acceptable when clearly labeled as such; presenting undisclosed AI review as your own reading is not.</li></ul>`,23)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
